    ('fee2da6d-ac67-4e7c-92b9-fbb82ae6bf8a'::uuid, 'raw_data', '{"_card_provenance": {"v": 2, "ai": "generated", "run": "wb-cardgap-2026-10-07", "kind": "teaser", "lane": "WB", "check": {"at": "2026-10-07T14:11:05+00:00", "by": "teaser-check-012", "stage": "check", "claims": [{"claim": "the route spans 600 km", "support": ["S1"]}, {"claim": "the route is in Serbia", "support": ["S1"]}, {"claim": "the route includes the Roman cities of Sirmium, Felix Romuliana and Naissus", "support": ["S3"]}, {"claim": "17 Roman emperors were born within Serbia", "support": ["S2"]}], "verdict": "PASS"}, "verify": {"at": "2026-10-07T16:39:37+00:00", "by": "teaser-verify-036", "stage": "verify", "claims": 9, "verdict": "VERIFIED", "unproven": 1, "text_sha256": "a73624af2573a4bba795d0ec0cfbf35b53c432ac71e46e12d4768fab1277953a"}, "ai_system": "Claude (Anthropic) and MiniMax M3.1 Flash (MiniMax): anthropic/claude-opus-5-5, anthropic/claude-sonnet-5-5, minimax/MiniMax-M3.1-Flash-Preview, an-sites-remediation-2026-09", "web_facts": [], "desc_sha256": "0c19068e913a41dbe338b12ed8322fb705a5de00b227ec788748ff4e3a6b6e01", "text_sha256": "a73624af2573a4bba795d0ec0cfbf35b53c432ac71e46e12d4768fab1277953a"}, "description_citations": [{"n": 1, "url": "https://en.wikipedia.org/w/index.php?title=Roman_Emperors_Route&oldid=1369018720", "title": "Wikipedia: Roman Emperors Route", "domain": "en.wikipedia.org", "license": "CC BY-SA 4.0"}], "_description_provenance": {"v": 1, "ai": "selected", "run": "mass-2026-09-25", "card": null, "lane": "W", "licence": "CC BY-SA 4.0", "sources": [{"id": "W", "url": "https://en.wikipedia.org/w/index.php?title=Roman_Emperors_Route&oldid=1369018720", "revid": 1369018720, "licence": "CC BY-SA 4.0", "text_sha256": "947fac005a4691bc227e4c493da3449db39c375679769e105fa6582b71154d61", "rev_timestamp": "2026-08-12T11:06:45Z"}], "ai_system": "Claude Opus (Anthropic): anthropic/claude-opus-5-5 (Claude Code agent), an-sites-remediation-2026-09", "sentences": [{"n": 1, "end": 293, "